def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def act1(n): return ' Sólo puedes activar 1 "%s" por turno.' % n
G = '"Ghostrick"'
B = 'No puede ser Invocada de Modo Normal, a menos que controles un monstruo ' + G + '. Una vez por turno: puedes cambiar esta carta a Posición de Defensa boca abajo. '
FD = 'Los monstruos no pueden atacar a monstruos en Posición de Defensa boca abajo, pero pueden atacar directamente si todos los monstruos que controla su adversario están en Posición de Defensa boca abajo. '
FLIP = 'Cuando esta carta sea volteada boca arriba: '
ES = {
"Ghostrick Museum": 'Los monstruos que controlas, excepto los monstruos ' + G + ', no pueden atacar. ' + FD + 'Al final del Damage Step, si un monstruo infligió daño de batalla a un jugador durante esta batalla: cambia ese monstruo o monstruos a Posición de Defensa boca abajo.',
"Ghostrick Stein": B + 'Cuando esta carta inflija daño de batalla a tu adversario: puedes añadir a tu mano 1 Carta Mágica/de Trampa ' + G + ' de tu Deck.' + once("Ghostrick Stein"),
"Ghostrick Nekomusume": B + 'Cuando uno o más monstruos de Nivel 4 o mayor sean Invocados de Modo Normal o Especial: cambia ese monstruo o monstruos a Posición de Defensa boca abajo. Debe haber otro monstruo ' + G + ' en el Campo para activar y resolver este efecto.',
"Ghostrick or Treat": 'Si controlas una Mágica de Campo ' + G + ' o un Monstruo de Enlace ' + G + ': puedes seleccionar 1 monstruo boca arriba que controle tu adversario; tu adversario puede pagar 2000 LP para que el efecto de esta carta sea "Coloca esta carta en vez de mandarla al Cementerio después de su activación"; si no, durante el resto de este turno, ese monstruo boca arriba no puede atacar, sus efectos quedan negados y, además, se cambia a Posición de Defensa boca abajo durante la End Phase.' + act1("Ghostrick or Treat"),
"Ghostrick Witch": B + 'Una vez por turno: puedes seleccionar 1 monstruo boca arriba que controle tu adversario; cámbialo a Posición de Defensa boca abajo.',
"Ghostrick Parade": FD + 'Tu adversario no recibe daño. Cuando un monstruo del adversario declare un ataque directo: puedes añadir a tu mano 1 carta ' + G + ' de tu Deck.',
"Ghostrick Socuteboss": '2 monstruos de Nivel 2\nMientras controles otro monstruo ' + G + ', los monstruos de tu adversario no pueden seleccionar esta carta para sus ataques. Una vez por turno: puedes desacoplar 1 material de esta carta y, después, seleccionar 1 monstruo en el Campo con ATK menor o igual que el ATK combinado de todos los monstruos ' + G + ' en el Campo; destrúyelo y, si lo haces, esa Zona de Monstruos no puede ser usada mientras controles un monstruo ' + G + '.',
"Ghostrick Fairy": B + FLIP + 'puedes seleccionar 1 carta ' + G + ' en tu Cementerio; Coloca esa carta (pero destiérrala cuando deje el Campo) y, después, puedes cambiar a Posición de Defensa boca abajo monstruos boca arriba que controle tu adversario, hasta el número de cartas Colocadas que controles.',
"Ghostrick-Go-Round": 'Una vez por turno, durante la Battle Phase: puedes activar 1 de estos efectos.\n● Selecciona 1 monstruo ' + G + ' que controles; cambia ese objetivo a Posición de Defensa boca abajo y, si lo haces, cambia a Posición de Ataque boca arriba 1 monstruo en Posición de Defensa boca abajo que controle tu adversario.\n● Selecciona 1 monstruo en Posición de Defensa boca abajo que controles; cambia ese objetivo a Posición de Ataque boca arriba y, si es un monstruo ' + G + ', cambia a Posición de Defensa boca abajo 1 monstruo boca arriba que controle tu adversario.',
"Ghostrick Dullahan": '2 monstruos de Nivel 1\nEsta carta gana 200 ATK por cada carta ' + G + ' que controles. Una vez por turno (Efecto Rápido): puedes desacoplar 1 material de esta carta y, después, seleccionar 1 monstruo boca arriba en el Campo; reduce a la mitad su ATK, hasta el final de este turno. Si esta carta es mandada al Cementerio: puedes seleccionar 1 otra carta ' + G + ' en tu Cementerio; añade ese objetivo a tu mano.',
"Ghostrick Doll": B + FLIP + 'durante la End Phase, cambia a Posición de Defensa boca abajo tantos monstruos boca arriba en el Campo como sea posible y, después, puedes Invocar de Modo Especial desde tu Deck en Posición de Defensa boca abajo 1 monstruo ' + G + ' cuyo Nivel sea menor o igual que el número de monstruos volteados boca abajo por este efecto.',
"Ghostrick Vanish": 'Revela 1 monstruo ' + G + ' en tu mano; este turno, las cartas ' + G + ' que controles, y los monstruos en Posición de Defensa boca abajo que controles, no pueden ser seleccionados ni destruidos por efectos de cartas.',
"Ghostrick Skeleton": B + FLIP + 'destierra boca abajo cartas de la parte superior del Deck de tu adversario, hasta el número de monstruos ' + G + ' que controles.' + once("Ghostrick Skeleton"),
"Ghostrick Angel of Mischief": '2 monstruos de Nivel 4\nTambién puedes Invocar por Xyz esta carta usando como material un Monstruo Xyz ' + G + ' que controles, excepto "Ghostrick Angel of Mischief". (Transfiere sus materiales a esta carta.) Cuando el número de materiales en esta carta llegue a 10, ganas el Duelo. Una vez por turno: puedes desacoplar 1 material de esta carta; añade a tu mano 1 Mágica/Trampa ' + G + ' de tu Deck. Una vez por turno: puedes acoplar a esta carta como material 1 carta ' + G + ' de tu mano.',
"Ghostrick Yuki-onna": B + 'Cuando esta carta sea destruida en batalla y mandada al Cementerio: puedes cambiar el monstruo que la destruyó a Posición de Defensa boca abajo y, si lo haces, no puede cambiar su posición de batalla.',
"Ghostrick Lantern": B + 'Cuando un monstruo del adversario declare un ataque directo, o cuando un monstruo ' + G + ' que controles sea seleccionado para un ataque: puedes negar el ataque y, si lo haces, Invoca esta carta de Modo Especial desde tu mano en Posición de Defensa boca abajo.',
"Ghostrick Jackfrost": B + 'Cuando un monstruo del adversario declare un ataque directo: puedes cambiar ese monstruo del adversario a Posición de Defensa boca abajo y, si lo haces, Invoca esta carta de Modo Especial desde tu mano en Posición de Defensa boca abajo.',
"Ghostrick Renovation": 'Selecciona 1 Mágica de Campo ' + G + ' en tu Zona de Campo; devuélvela a la mano y, después, puedes activar 1 Mágica de Campo de tu mano o Deck. Puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 Monstruo Xyz ' + G + ' que controles; Invoca de Modo Especial desde tu Extra Deck 1 Monstruo Xyz ' + G + ' con un nombre diferente, usando ese objetivo como material. (Esto se trata como una Invocación por Xyz. Transfiere sus materiales al monstruo Invocado.)' + once("Ghostrick Renovation"),
"Ghostrick Siren": 'No puede ser Invocada de Modo Normal, a menos que controles un monstruo ' + G + '. Una vez por turno, durante tu Main Phase: puedes cambiar esta carta a Posición de Defensa boca abajo. Si esta carta es Invocada de Modo Normal o volteada boca arriba: manda al Cementerio las 2 cartas superiores de tu Deck y, después, si cualquiera de ellas era una carta ' + G + ', puedes aplicar 1 de estos efectos.\n● Añade a tu mano 1 Mágica/Trampa ' + G + ' de tu Deck.\n● Cambia a Posición de Defensa boca abajo 1 Monstruo de Efecto que controle tu adversario.',
"Ghostrick Shot": 'Invoca de Modo Especial 1 monstruo ' + G + ' de tu mano o Cementerio y, después, puedes cambiar a Posición de Ataque boca arriba 1 monstruo ' + G + ' boca abajo que controles. Puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 Monstruo Xyz ' + G + ' que controles; acopla a ese monstruo como material 1 carta ' + G + ' de tu Cementerio.' + each("Ghostrick Shot"),
"Ghostrick Warwolf": B + FLIP + 'inflige a tu adversario 100 de daño por cada carta Colocada en el Campo.' + once("Ghostrick Warwolf"),
"Ghostrick Break": 'Cuando exactamente 1 monstruo ' + G + ' boca arriba que controles (y ninguna otra carta) sea destruido en batalla o por un efecto de carta del adversario y mandado a tu Cementerio: selecciona 2 monstruos ' + G + ' en tu Cementerio con nombres diferentes del monstruo destruido; Invócalos de Modo Especial en Posición de Defensa boca abajo.',
"Ghostrick Jiangshi": B + FLIP + 'puedes añadir a tu mano desde tu Deck 1 monstruo ' + G + ' cuyo Nivel sea menor o igual que el número de monstruos ' + G + ' que controles.' + once("Ghostrick Jiangshi"),
"Ghostrick Specter": B + 'Cuando un monstruo ' + G + ' sea destruido por un efecto de carta del adversario, o en batalla con su monstruo atacante, y mandado a tu Cementerio: puedes Invocar esta carta de Modo Especial desde tu mano en Posición de Defensa boca abajo y, si lo haces, roba 1 carta.',
"Ghostrick Yeti": B + FLIP + 'puedes seleccionar 1 monstruo ' + G + ' en el Campo; este turno, no puede ser destruido en batalla ni por efectos de cartas.',
"Ghostrick Ghoul": B + 'Una vez por turno, durante tu Main Phase 1: puedes seleccionar 1 monstruo ' + G + ' que controles; su ATK pasa a ser igual al ATK original combinado de todos los monstruos ' + G + ' en el Campo en ese momento, hasta el final del próximo turno de tu adversario, pero si lo hace, sólo ese monstruo puede atacar este turno.',
"Ghostrick Night": 'Mientras haya un monstruo ' + G + ' en el Campo, tu adversario no puede Invocar por Volteo. Si esta carta en tu posesión es destruida por tu adversario y mandada a tu Cementerio: tu adversario no puede declarar ataques durante el resto de este turno.',
"Ghostrick Scare": 'Selecciona cualquier número de monstruos en Posición de Defensa boca abajo que controles; cámbialos a Posición de Defensa boca arriba, cuenta el número de monstruos ' + G + ' entre ellos y, si lo haces, cambia a Posición de Defensa boca abajo hasta ese número de monstruos boca arriba que controle tu adversario (mín. 1).',
"Ghostrick Mummy": B + 'Mientras esta carta esté boca arriba en el Campo, puedes Invocar de Modo Normal 1 monstruo ' + G + ' además de tu Invocación Normal o Colocación. (Sólo puedes ganar este efecto una vez por turno.) No puedes Invocar de Modo Especial ningún monstruo, excepto monstruos de OSCURIDAD.',
"Ghostrick Mary": B + 'Cuando recibas daño: puedes descartar esta carta; Invoca de Modo Especial 1 monstruo ' + G + ' de tu Deck en Posición de Defensa boca abajo.' + once("Ghostrick Mary"),
"Ghostrick Mansion": FD + 'Todo el daño de efecto, y el daño de batalla infligido por monstruos distintos de los monstruos ' + G + ', se reduce a la mitad.',
}
